import json
from pathlib import Path


def task_func():
    with Path('inputs/actions.json').open('r', encoding='utf-8') as source:
        data = json.load(source)

    providers = {}
    for row in data['action_tasks']:
        provider = row['provider']
        if provider not in providers:
            providers[provider] = {
                'accepted': 0,
                'failed': 0,
                'unknown_acceptance': 0,
                'known_reported_micro_usd': 0,
                'unknown_costs': 0,
                'positive_utility': 0,
                'unknown_utility': 0,
            }
        counts = providers[provider]

        acceptance = row.get('acceptance_passed')
        if acceptance is True:
            counts['accepted'] += 1
        elif acceptance is False:
            counts['failed'] += 1
        else:
            counts['unknown_acceptance'] += 1

        cost = row.get('settled_micro_usd')
        if type(cost) is int:
            counts['known_reported_micro_usd'] += cost
        else:
            counts['unknown_costs'] += 1

        utility = row.get('outcome_utility')
        if type(utility) in (int, float):
            if utility > 0:
                counts['positive_utility'] += 1
        else:
            counts['unknown_utility'] += 1

    report = {
        'reported_actions': len(data['action_tasks']),
        'financial_execution': data['financial_execution'],
        'payment_attestation': 'unknown',
        'evidence': 'reported_public_projection_only',
        'providers': providers,
    }
    with Path('report.json').open('w', encoding='utf-8') as destination:
        json.dump(report, destination, indent=2)
        destination.write('\n')
    return report
